import 'dart:collection';

class Transaction {
  final String coinName;
  final DateTime dateTime;
  final double profitLoss; // Positive for profit, negative for loss

  Transaction({required this.coinName, required this.dateTime, required this.profitLoss});
}

Future<Map<String, dynamic>> analyzeProfitLoss(List<Transaction> transactions) async {
  // Group transactions by coin name for aggregation
  final groupedTransactions = transactions.groupBy((txn) => txn.coinName);

  // Calculate average profit/loss per coin
  final avgProfits = <String, double>{};
  final avgLosses = <String, double>{};
  for (var (coin, coinTransactions) in groupedTransactions.entries) {
    double totalProfit = 0;
    double totalLoss = 0;
    for (var txn in coinTransactions) {
      totalProfit += txn.profitLoss;
      totalLoss -= txn.profitLoss; // Invert for loss calculation
    }
    avgProfits[coin] = totalProfit / coinTransactions.length;
    avgLosses[coin] = totalLoss / coinTransactions.length;
  }

  // Extract top 3 with highest average profit and loss
  List<MapEntry<String, double>> sortedProfits = avgProfits.entries.toList()
    ..sort((a, b) => b.value.compareTo(a.value));
  List<MapEntry<String, double>> sortedLosses = avgLosses.entries.toList()
    ..sort((a, b) => a.value.compareTo(b.value)); // Sort in ascending order for losses

  return {
    'topProfits': sortedProfits.sublist(0, 3).map((e) => {'coin': e.key, 'average': e.value}).toList(),
    'topLosses': sortedLosses.sublist(0, 3).map((e) => {'coin': e.key, 'average': e.value}).toList(),
  };
}

// Example Usage (assuming you have your 'transactions' List populated)
analyzeProfitLoss(transactions)
  .then((result) => print(result)) // Print formatted result with top coins and averages
  .catchError((error) => print('Error analyzing: $error'));
```

