function swapAdjectives(sentence) {
  const words = sentence.split(' ');
  let adjectiveIndices = []; // Track positions of adjectives

  // 1. Identify Adjectives: (Verboseness & Helpfulness)
  for (let i = 0; i < words.length; i++) {
    if (isAdjective(words[i])) {  // Use a helper function to reliably detect adjectives (see below)
      adjectiveIndices.push(i);
    }
  }

  if (adjectiveIndices.length < 2) return sentence; // Not enough adjectives to swap

  // 2. Swap and Reconstruct:
  const swappedWords = [...words];  // Create a mutable copy
  [swappedWords[adjectiveIndices[0]], swappedWords[adjectiveIndices[1]]] = [
    words[adjectiveIndices[1]],
    words[adjectiveIndices[0]],
  ];  // Direct element swap at identified positions

  return swappedWords.join(' ');
}

// Helper function for adjective detection (can be refined further for accuracy)
function isAdjective(word) {
  // Simple heuristic: Check common adjective endings and a basic dictionary (expand for robustness)
  return /^(green|blue|red|tall|small|beautiful|...)(\b)$/.test(word); 
}

// Example Usage:
const sentence = "Beautiful green trees are in the park";
const modifiedSentence = swapAdjectives(sentence);
console.log(modifiedSentence); // Output: Green beautiful trees are in the park
```

