using namespace std;

// Recursive Fibonacci function with error handling
pair<long long, bool> fibonacci(long long a, long long b, int n, bool& isValid) {
    if (n <= 0) {  // Base case: Generate zero elements, signal validity
        isValid = true;
        return make_pair(0, true);
    } else if (n == 1) {  // Base case: Return the first element
        isValid = true;
        return make_pair(a, true);
    } else {
        long long next = a + b;
        isValid &= (a >= 0 && b >= 0 && next >= 0); // Ensure non-negative values
        return fibonacci(b, next, n - 1, isValid); // Recursive call
    }
}

