    let excelData: [[String]] = [[
        "Factor", "Skiing", "Snowboarding"
    ]]

    //  Define pro/con data with emphasis based on preference
    var skiingStrengths = ["Speed": "High", "Terrain Variety": "Excellent", "Learning Curve": "Moderate initially, advanced techniques steeper", "Trick Opportunities": "Limited freestyle options"]
    var snowboardingStrengths = ["Style": "Highly expressive", "Trick Opportunities": "Vast & progressive", "Terrain Variety": "Adaptable to diverse slopes", "Learning Curve": "Steeper initial phase, rewarding progression"]

