        // Emphasize Skiing strengths
        skiingStrengths["Speed"] = "**Exceptional**"
        skiingStrengths["Terrain Variety"] = "**Highly Diverse**"
        snowboardingStrengths["Trick Opportunities"] = "Developing but less established" // Subtle de-emphasis
    } else if sportPreference == "snowboarding" {
