using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json; // Or your preferred JSON serialization library

public class RestServiceWrapper<T> where T : class
{
    private readonly HttpClient _client;
    private readonly string _baseUrl;
    private string _authToken;

    public RestServiceWrapper(string baseUrl, string initialAuthToken = null)
    {
        _baseUrl = baseUrl;
        _authToken = initialAuthToken;
        _client = new HttpClient { BaseAddress = new Uri(_baseUrl) };
        // Add default headers (e.g., Content-Type) as needed
        _client.DefaultRequestHeaders.Add("Accept", "application/json"); 
    }

    /// <summary>
    ///  Set a fresh authentication token for subsequent requests.
    /// </summary>
    public void SetAuthToken(string authToken)
    {
        _authToken = authToken;
        _client.DefaultRequestHeaders.Add("Authorization", $"Bearer {_authToken}"); // Common bearer token format
    }

    /// <summary>
    ///  Generic GET request handler with automatic token inclusion.
    /// </summary>
    public async Task<T> GetAsync(string apiEndpoint, params KeyValuePair<string, string>[] queryParameters)
    {
        var uri = BuildUri(apiEndpoint, queryParameters);
        var response = await _client.GetAsync(uri);
        return await HandleResponse<T>(response);
    }

    /// <summary>
    /// Generic POST request handler with automatic token inclusion and payload serialization.
    /// </summary>
    public async Task<T> PostAsync<TPayload>(string apiEndpoint, TPayload data, params KeyValuePair<string, string>[] headers)
        where TPayload : class
    {
        var content = JsonConvert.SerializeObject(data);
        var request = new StringContent(content, System.Text.Encoding.UTF8, "application/json");

        // Add extra headers if provided
        foreach (var header in headers)
            _client.DefaultRequestHeaders.Add(header.Key, header.Value);

        var response = await _client.PostAsync(apiEndpoint, request);
        return await HandleResponse<T>(response);
    }

