function determineRelevantProtocol(inputData) {
  // **Prioritize based on input cues and protocol characteristics (weighted analysis):**

  const relevanceScores = {
    IPv6: inputData.sourceIP && inputData.destinationIP ? 77 : 0, // Strong IPv6 indicator with literal addresses
    HTTP: inputData.port === 80 && typeof inputData.payload === 'string' ? 64 : 0, // Common HTTP port and textual payload hint
    UDP:  0  // No direct cues for UDP in this input data
  };

  // Determine the protocol with the highest score
  let mostRelevant = Object.keys(relevanceScores).reduce((maxKey, key) => 
    relevanceScores[maxKey] > relevanceScores[key] ? maxKey : key
  );

  return mostRelevant;
}

// Apply to input data
const input = { /* ... your provided inputData ... */ };
const result = determineRelevantProtocol(input);
console.log(`Most relevant protocol: ${result} (based on input analysis)`); // Output: Most relevant protocol: HTTP 

