function geocodeAndPopulate(spreadsheetId, sheetName, placeColumn, latColumn, lngColumn) {
  // 1. Access Spreadsheet and Sheet
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(sheetName);

  // 2. Fetch Place Names from Column
  const dataRange = sheet.getRange(placeColumn); // Assuming your place names are in Column A (adjust if different)
  const placeNames = dataRange.getValues().map(row => row[0]); 

  // 3. Geocoding Loop (using Google Maps Places API)
  const placesService = new google.maps.places.PlacesService(SpreadsheetApp.getActive()); // Initialize Places Service
  for (let i = 0; i < placeNames.length; i++) {
    const placeName = placeNames[i];
    const request = {
      query: placeName,
      fields: ['geometry', 'name'], // Only fetch geometry (lat/lng) and name for efficiency
    };

    placesService.findPlaceFromQuery(request, (results, status) => {
      if (status === google.maps.places.PlacesServiceStatus.OK && results && results.length > 0) {
        const place = results[0];
        const lat = place.geometry.location.lat();
        const lng = place.geometry.location.lng();

        // 4. Update Spreadsheet with Lat/Lng
        const row = sheet.getRange(i + 2, latColumn).getRow(); // Start updating from row 2 (assuming header row)
        sheet.getRange(row, latColumn).setValue(lat);
        sheet.getRange(row, lngColumn).setValue(lng);
      } else {
        // Handle cases with no match (e.g., log an error or placeholder value)
        Logger.log(`Geocoding failed for "${placeName}" - Status: ${status}`);
        sheet.getRange(i + 2, latColumn).setValue("Geocoding Error"); 
        sheet.getRange(i + 2, lngColumn).setValue(""); 
      }
    });
  }
  Logger.log("Geocoding and population complete.");
}
